begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);
grant all on tap_results to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('50000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'role','authenticated','session_id',pg_temp.i(n),'is_anonymous',false)::text,true)$$;

create function pg_temp.ctx(b integer default 101) returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(b))$$;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;
set local role authenticated;select pg_temp.login(11);
do $$begin for n in 1..51 loop
 perform public.agri_command('record_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(1000+n),'productId',pg_temp.i(301),'quantity','0.001','category','damage','disposition','hold','reason','TEST held page fixture'));
 perform public.agri_command('approve_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(1000+n),'reason','TEST owner checked held page fixture'));
 perform public.agri_command('record_stock_issue',pg_temp.ctx()||jsonb_build_object('issueId',pg_temp.i(2000+n),'productId',pg_temp.i(301),'quantity','0.002','category','damage','disposition','write_off','reason','TEST pending page fixture'));
end loop;end$$;
reset role;
-- Tie timestamps and keep microseconds, proving that the UUID and original
-- timestamp cursor travel together without JavaScript Date truncation.
update public.stock_holds set created_at='2026-01-01 00:00:00.123456+00';
update public.stock_issues set created_at='2026-01-01 00:00:00.123456+00';
set local role authenticated;select pg_temp.login(11);
select pg_temp.login(12);
select pg_temp.login(14);
select pg_temp.login(15);
select pg_temp.login(11);
reset role;select line from tap_results;select * from finish();rollback;
