insert into saved values('first',public.agri_command('stock_controls',pg_temp.ctx()));
insert into saved values('second',public.agri_command('stock_controls',pg_temp.ctx()||jsonb_build_object('holdCursor',(select data->'holdsNext' from saved where name='first'),'issueCursor',(select data->'issuesNext' from saved where name='first'))));
insert into tap_results select is((select data->>'holdCount' from saved where name='first'),'51','All held records are counted, including the next page');
insert into tap_results select is((select data->>'issueCount' from saved where name='first'),'51','All pending stock issues are counted');
insert into tap_results select is((select jsonb_array_length(data->'holds') from saved where name='first'),50,'Held first page remains bounded');
insert into tap_results select is((select jsonb_array_length(data->'issues') from saved where name='first'),50,'Issue first page remains bounded');
insert into tap_results select matches((select data->'holdsNext'->>'at' from saved where name='first'),'123456','Held cursor retains timestamp microseconds');
insert into tap_results select matches((select data->'issuesNext'->>'at' from saved where name='first'),'123456','Issue cursor retains timestamp microseconds');
insert into tap_results select is((select jsonb_array_length(data->'holds') from saved where name='second'),1,'The fifty-first held record remains accessible');
insert into tap_results select is((select jsonb_array_length(data->'issues') from saved where name='second'),1,'The fifty-first pending issue remains accessible');
insert into tap_results select ok((select data->'holdsNext'='null'::jsonb and data->'issuesNext'='null'::jsonb from saved where name='second'),'Both completed pages have no false next cursor');
insert into tap_results select is((select count(distinct e->>'id')::integer from saved s cross join lateral jsonb_array_elements(s.data->'holds') e),51,'Tied held timestamps neither skip nor duplicate a record');
insert into tap_results select is((select count(distinct e->>'id')::integer from saved s cross join lateral jsonb_array_elements(s.data->'issues') e),51,'Tied issue timestamps neither skip nor duplicate a record');
insert into tap_results select is((select quantity from public.branch_inventory where branch_id=pg_temp.i(101) and product_id=pg_temp.i(301)),499.949::numeric,'Reading every page changes no saleable stock');
insert into tap_results select is(public.agri_command('stock_loss_report',pg_temp.ctx())->'totals'->>'lossRows','0','Unprocessed holds and pending issues do not become posted losses');
insert into tap_results select is((select sum(remaining) from public.stock_holds where branch_id=pg_temp.i(101)),0.051::numeric,'Reading pages retains all exact held quantities');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx()||'{"holdCursor":{"at":"2026-01-01"}}'::jsonb)$$,'P0001','Invalid held-goods position. Refresh stock controls','Partial held cursor is rejected');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx()||'{"issueCursor":{"id":"50000000-0000-4000-8000-000000002050"}}'::jsonb)$$,'P0001','Invalid stock-issue position. Refresh stock controls','Partial issue cursor is rejected');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx())$$,'42501',null,'Cashier cannot read paginated stock controls');
insert into tap_results select is(public.agri_command('stock_controls',pg_temp.ctx(102))->>'holdCount','0','Manager only sees held totals in the assigned branch');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx())$$,'42501',null,'Another branch cannot use a held or issue page');
insert into tap_results select throws_ok($$select public.agri_command('stock_controls',pg_temp.ctx())$$,'42501',null,'Another organization cannot read page counts or contents');
insert into tap_results select is((select sum(quantity) from public.inventory_movements where branch_id=pg_temp.i(101) and product_id=pg_temp.i(301)),(select quantity from public.branch_inventory where branch_id=pg_temp.i(101) and product_id=pg_temp.i(301)),'The stock ledger and projection still agree');
insert into tap_results select is((select count(*)::integer from public.payments),0,'Worklist reads and setup issue approvals create no cash payment');
